import 'package:flutter/material.dart';import '../core/app_config.dart';import '../core/chat_service.dart';
class SettingsScreen extends StatelessWidget{final ChatService service;const SettingsScreen({super.key,required this.service});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('Settings',style:TextStyle(fontSize:32,fontWeight:FontWeight.w800)),const SizedBox(height:18),Card(child:Column(children:[ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('@${service.username}'),subtitle:SelectableText(service.sessionId)),const Divider(height:1),ListTile(leading:const Icon(Icons.wifi),title:const Text('WebSocket'),subtitle:SelectableText(AppConfig.wsUrl),trailing:Text(service.status))])),const SizedBox(height:14),Card(child:Column(children:[const ListTile(leading:Icon(Icons.lock_outline),title:Text('Phiên tạm'),subtitle:Text('UID được lưu local để reconnect trong thời gian server còn giữ session.')),ListTile(leading:const Icon(Icons.restart_alt),title:const Text('Tạo phiên mới'),subtitle:const Text('Kết thúc session hiện tại và tạo UID mới.'),onTap:()=>showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('Tạo phiên mới?'),content:const Text('Các cuộc chat tạm hiện tại sẽ kết thúc.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Hủy')),FilledButton(onPressed:(){Navigator.pop(ctx);service.endSession();},child:const Text('Tạo mới'))]))) ])),const SizedBox(height:18),const Text('Cấu hình server bằng --dart-define=WS_URL=wss://your-server.example',style:TextStyle(color:Colors.black54))]);}
